script:
(function () {
  'use strict';
  // Depreciation schedules. B = cost - salvage, L = useful life in years.
  //   Straight-line: B / L a year.
  //   Declining balance: rate = factor / L applied to the start-of-year book value, never taking the
  //     book value below salvage; optional switch to straight-line ((book - salvage) / years left)
  //     when that is larger; without the switch the last year takes the book value down to salvage.
  //   Sum-of-the-years' digits: year k gets (L - k + 1) / (L(L + 1) / 2) of B.
  //   Units of production: B / total units per unit, capped at B.
  //   Partial first year (book methods): with f = months / 12, accounting year 1 gets f of asset
  //     year 1, year j gets (1 - f) of asset year j - 1 plus f of asset year j.
  //   MACRS: cost x IRS Pub. 946 Table A-1 percentage (GDS, half-year convention); salvage ignored.
  // Amounts are rounded to cents; the final year absorbs rounding so the total equals the base.
  // Verified (Node): SL $11,000 / $1,000 / 5 yrs -> $2,000 a year; DDB $10,000 / $1,000 / 5 yrs ->
  // 4,000, 2,400, 1,440, 864, 296 (textbook); SYD $11,000 / $1,000 / 5 -> 3,333.33, 2,666.67, 2,000,
  // 1,333.33, 666.67; MACRS 5-year $10,000 -> 2,000, 3,200, 1,920, 1,152, 1,152, 576; SL $12,000 / 0 /
  // 3 yrs placed in service with 6 months left -> 2,000, 4,000, 4,000, 2,000; every Table A-1 column
  // sums to 100%.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  // IRS Publication 946 (2025), Appendix A, Table A-1: 3-, 5-, 7-, 10-, 15- and 20-year property,
  // half-year convention (percent of unadjusted basis). Checked against irs.gov/pub/irs-pdf/p946.pdf.
  var MACRS_HALF_YEAR = {
    3: [33.33, 44.45, 14.81, 7.41],
    5: [20.00, 32.00, 19.20, 11.52, 11.52, 5.76],
    7: [14.29, 24.49, 17.49, 12.49, 8.93, 8.92, 8.93, 4.46],
    10: [10.00, 18.00, 14.40, 11.52, 9.22, 7.37, 6.55, 6.55, 6.56, 6.55, 3.28],
    15: [5.00, 9.50, 8.55, 7.70, 6.93, 6.23, 5.90, 5.90, 5.91, 5.90, 5.91, 5.90, 5.91, 5.90, 5.91, 2.95],
    20: [3.750, 7.219, 6.677, 6.177, 5.713, 5.285, 4.888, 4.522, 4.462, 4.461, 4.462, 4.461, 4.462, 4.461,
         4.462, 4.461, 4.462, 4.461, 4.462, 4.461, 2.231]
  };

  // --- calc start
  function straightLine(base, life) {
    var out = [];
    for (var y = 0; y < life; y++) out.push(base / life);
    return out;
  }

  function sumOfYears(base, life) {
    var sum = life * (life + 1) / 2, out = [];
    for (var y = 1; y <= life; y++) out.push(base * (life - y + 1) / sum);
    return out;
  }

  function decliningBalance(cost, salvage, life, factor, switchToSl) {
    var rate = factor / life, book = cost, out = [];
    for (var y = 1; y <= life; y++) {
      var d = book * rate;
      if (switchToSl) d = Math.max(d, (book - salvage) / (life - y + 1));
      d = Math.min(d, Math.max(book - salvage, 0));
      if (y === life) d = Math.max(book - salvage, 0);
      out.push(d);
      book -= d;
    }
    return out;
  }

  function unitsOfProduction(base, totalUnits, units) {
    var perUnit = base / totalUnits, left = base, out = [];
    for (var y = 0; y < units.length; y++) {
      var d = Math.min(units[y] * perUnit, left);
      out.push(d);
      left -= d;
    }
    return out;
  }

  function spreadFirstYear(assetYears, months) {
    if (months >= 12) return assetYears.slice();
    var f = months / 12, out = [];
    for (var j = 0; j <= assetYears.length; j++) {
      var prev = j > 0 ? assetYears[j - 1] : 0, cur = j < assetYears.length ? assetYears[j] : 0;
      out.push((1 - f) * prev + f * cur);
    }
    return out;
  }

  function macrs(cost, recovery) {
    return MACRS_HALF_YEAR[recovery].map(function (p) { return cost * p / 100; });
  }

  // Round to cents; when fullBase is given, the last year absorbs the rounding difference.
  function toCents(deps, fullBase) {
    var out = deps.map(function (d) { return Math.round(d * 100) / 100; });
    if (fullBase !== null && out.length) {
      var others = 0;
      for (var i = 0; i < out.length - 1; i++) others += out[i];
      out[out.length - 1] = Math.round((fullBase - others) * 100) / 100;
    }
    return out;
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function show(id, on) { el(id).hidden = !on; }
  function pct(x, dp) {
    return (x * 100).toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }) + '%';
  }

  function clear() {
    ['dpFirst', 'dpTotal', 'dpBook', 'dpYears', 'dpBasis', 'dpRateInfo', 'dpAverage'].forEach(function (id) {
      el(id).textContent = '–';
    });
    el('dpSchedule').innerHTML = '';
    el('dpNote').hidden = true;
  }

  function update() {
    var method = el('dpMethod').value;
    var isMacrs = method === 'macrs', isUnits = method === 'units';
    show('dpSalvageWrap', !isMacrs);
    show('dpLifeWrap', !isMacrs && !isUnits);
    show('dpDbWrap', method === 'db');
    show('dpUnitsWrap', isUnits);
    show('dpMacrsWrap', isMacrs);
    show('dpMoreWrap', !isMacrs && !isUnits);
    show('dpMacrsNote', isMacrs);

    var cost = parseFloat(el('dpCost').value);
    var salvageText = el('dpSalvage').value.trim();
    var salvage = isMacrs ? 0 : (salvageText === '' ? 0 : parseFloat(salvageText));
    var life = parseFloat(el('dpLife').value), factor = parseFloat(el('dpFactor').value);
    var totalUnits = parseFloat(el('dpTotalUnits').value);
    var months = parseInt(el('dpMonths').value, 10) || 12;
    var recovery = parseInt(el('dpClass').value, 10);
    var units = [], unitsBad = false;
    if (isUnits) {
      el('dpUnits').value.split(/[,;\s]+/).forEach(function (part) {
        if (part === '') return;
        var v = parseFloat(part);
        if (!isFinite(v) || v < 0 || !/^[0-9.]+$/.test(part)) unitsBad = true; else units.push(v);
      });
    }

    var msg = '';
    if (isNaN(cost) || cost <= 0 || cost > 1e12) msg = 'Enter an asset cost above $0 and up to $1 trillion.';
    else if (isNaN(salvage) || salvage < 0 || salvage >= cost) msg = 'Salvage value must be $0 or more and less than the cost.';
    else if (!isMacrs && !isUnits && (isNaN(life) || life < 1 || life > 50 || Math.round(life) !== life)) msg = 'Enter a useful life of 1 to 50 whole years.';
    else if (method === 'db' && (isNaN(factor) || factor <= 0 || factor > 5)) msg = 'Enter a declining balance factor between 0 and 5.';
    else if (isUnits && (isNaN(totalUnits) || totalUnits <= 0 || totalUnits > 1e12)) msg = 'Enter the total units the asset will produce over its life.';
    else if (isUnits && unitsBad) msg = 'Units used each year must be numbers of 0 or more, separated by commas.';
    else if (isUnits && !units.length) msg = 'Enter the units used in at least one year.';
    else if (isUnits && units.length > 60) msg = 'Enter up to 60 years of units.';
    else if (isMacrs && !MACRS_HALF_YEAR[recovery]) msg = 'Choose a MACRS property class.';
    var error = el('dpError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    var base = cost - salvage, deps, fullBase = base, rateInfo;
    if (method === 'sl') {
      deps = spreadFirstYear(straightLine(base, life), months);
      rateInfo = pct(1 / life, 2) + ' of the depreciable amount a year';
    } else if (method === 'syd') {
      deps = spreadFirstYear(sumOfYears(base, life), months);
      rateInfo = 'Year 1 gets ' + life + '/' + (life * (life + 1) / 2) + ' of the depreciable amount';
    } else if (method === 'db') {
      var switchToSl = el('dpSwitch').checked;
      deps = spreadFirstYear(decliningBalance(cost, salvage, life, factor, switchToSl), months);
      rateInfo = pct(Math.min(factor / life, 1), 2) + ' of book value a year';
    } else if (method === 'units') {
      deps = unitsOfProduction(base, totalUnits, units);
      var used = units.reduce(function (a, b) { return a + b; }, 0);
      if (used < totalUnits) fullBase = null;
      rateInfo = money.format(base / totalUnits) + ' per unit';
    } else {
      deps = macrs(cost, recovery);
      rateInfo = 'IRS Table A-1, ' + recovery + '-year property';
    }
    deps = toCents(deps, fullBase);

    var total = 0, accumulated = 0;
    deps.forEach(function (d) { total += d; });
    var note = el('dpNote');
    note.hidden = true;
    if (isUnits && fullBase === null) {
      note.textContent = 'The units entered add up to less than the total, so part of the cost is not yet depreciated.';
      note.hidden = false;
    } else if (method === 'db' && !el('dpSwitch').checked && factor / life < 1) {
      note.textContent = 'Without the switch to straight-line, the final year takes whatever is needed to bring the book value down to the salvage value.';
      note.hidden = false;
    }

    el('dpFirst').textContent = money.format(deps[0] || 0);
    el('dpTotal').textContent = money.format(total);
    el('dpBook').textContent = money.format(cost - total);
    el('dpYears').textContent = String(deps.length);
    el('dpBasis').textContent = money.format(base);
    el('dpRateInfo').textContent = rateInfo;
    el('dpAverage').textContent = money.format(total / deps.length);
    el('dpSchedule').innerHTML = deps.map(function (d, i) {
      accumulated += d;
      var book = Math.round((cost - accumulated) * 100) / 100;
      return '<tr><td>' + (i + 1) + '</td><td>' + money.format(d) + '</td><td>' + pct(d / cost, 2) + '</td><td>' +
             money.format(accumulated) + '</td><td>' + money.format(Math.abs(book) < 0.005 ? 0 : book) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('dpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
